            ("デッド", "デッドリフト"), ("ランジ", "ブルガリアンスクワット"), ("片脚", "ブルガリアンスクワット"),
            ("スクワット", "スクワット"), ("レッグプレス", "レッグプレス"), ("ヒップ", "ヒップスラスト"),
            ("ノルディック", "ノルディックハムストリング"), ("カーフ", "カーフレイズ"), ("クリーン", "パワークリーン"),
            ("スナッチ", "パワークリーン"), ("ショルダー", "ショルダープレス"), ("レイズ", "サイドレイズ"),
            ("カール", "バーベルカール"), ("エクステンション", "トライセプスエクステンション"), ("プランク", "プランク"),
            ("坂", "坂道ダッシュ"), ("そり", "そり引きダッシュ"), ("ソリ", "そり引きダッシュ"), ("ダッシュ", "30mダッシュ"),
            ("スプリント", "30mダッシュ"), ("走", "ランニング"), ("ボックス", "ボックスジャンプ"), ("バウンド", "バウンディング"),
            ("幅跳", "立ち幅跳び"), ("ジャンプ", "ボックスジャンプ"), ("跳", "ボックスジャンプ"), ("メディシン", "ショルダープレス"),
            ("プレス", "ベンチプレス"),
        ]
        if let match = keywords.first(where: { name.contains($0.0) }), let pose = poses[match.1] { return pose }
        let fallback: String = switch group {
        case .chest: "ベンチプレス"
        case .back: "ラットプルダウン"
        case .legs: "スクワット"
        case .shoulders: "ショルダープレス"
        case .arms: "バーベルカール"
        case .core: "プランク"
        case .sprint: "30mダッシュ"
        case .plyometric: "ボックスジャンプ"
        case .cardio: "ランニング"
        }
        return poses[fallback] ?? []
    }
}

/// ピクトグラムを描く。
struct PictogramView: View {
    let elements: [Pictogram.Element]

    var body: some View {
        Canvas { context, size in
            let scale = min(size.width, size.height) / 100
            func point(_ x: Double, _ y: Double) -> CGPoint { CGPoint(x: x * scale, y: y * scale) }
            let body = GraphicsContext.Shading.color(.white)
            let prop = GraphicsContext.Shading.color(.white.opacity(0.72))
            func stroke(_ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double, width: Double, _ shading: GraphicsContext.Shading) {
                var path = Path()
                path.move(to: point(x1, y1))
                path.addLine(to: point(x2, y2))
                context.stroke(path, with: shading, style: StrokeStyle(lineWidth: max(1, width) * scale, lineCap: .round))
            }
            for element in elements {
                switch element {
                case let .limb(x1, y1, x2, y2):
                    stroke(x1, y1, x2, y2, width: 7, body)
                case let .head(x, y):
                    context.fill(Path(ellipseIn: CGRect(x: (x - 6.5) * scale, y: (y - 6.5) * scale, width: 13 * scale, height: 13 * scale)), with: body)
                case let .bar(x1, y1, x2, y2, width):
                    stroke(x1, y1, x2, y2, width: width, prop)
                case let .plate(x, y, r):
                    context.fill(Path(ellipseIn: CGRect(x: (x - r) * scale, y: (y - r) * scale, width: 2 * r * scale, height: 2 * r * scale)), with: prop)
                case let .dumbbell(x, y, angle):
                    let radians = angle * .pi / 180
                    let dx = cos(radians) * 7, dy = sin(radians) * 7
                    stroke(x - dx, y - dy, x + dx, y + dy, width: 3, prop)
                    for end in [-1.0, 1.0] {
                        let cx = x + dx * end, cy = y + dy * end
                        context.fill(Path(ellipseIn: CGRect(x: (cx - 3.5) * scale, y: (cy - 3.5) * scale, width: 7 * scale, height: 7 * scale)), with: prop)
                    }
                case let .box(x, y, w, h):
                    context.fill(Path(roundedRect: CGRect(x: x * scale, y: y * scale, width: w * scale, height: h * scale), cornerRadius: 2 * scale), with: prop)
                case let .speed(x, y, length):
                    for index in 0..<3 {
                        let offset = Double(index)
                        stroke(x, y + offset * 7, x + length - offset * 3, y + offset * 7, width: 2.5, prop)
                    }
                case let .arrow(x1, y1, x2, y2):
                    stroke(x1, y1, x2, y2, width: 3, prop)
                    let angle = atan2(y2 - y1, x2 - x1)
                    for side in [-1.0, 1.0] {
                        let a = angle + .pi - side * 0.5
                        stroke(x2, y2, x2 + cos(a) * 7, y2 + sin(a) * 7, width: 3, prop)
                    }
                }
            }
        }
    }
}
